begin;
create extension if not exists pgtap with schema extensions;
select plan(24);
update private.runtime_settings set environment='test',simulations_enabled=true;
insert into auth.users(id) values('00000000-0000-4000-8000-000000000001'),('00000000-0000-4000-8000-000000000002'),('00000000-0000-4000-8000-000000000003');
insert into public.tenants(id,name,demo) values('10000000-0000-4000-8000-000000000001','A',true),('10000000-0000-4000-8000-000000000002','B',false);
insert into public.sites(id,tenant_id,name) values('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','A1'),('20000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002','B1'),('20000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000001','A2');
insert into public.memberships(tenant_id,site_id,user_id,role,capabilities) values('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001','RESIDENT',array['visits.invite','rides.request']),('10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000002','RESIDENT',array['rides.request']),('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000003','STAFF',array['fleet.drive','fleet.dispatch','visits.read.site','visits.checkin','parking.configure','parking.simulate']);
insert into public.parking_zones(id,tenant_id,site_id,name,capacity) values('30000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','A zone',2),('30000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002','B zone',4);
insert into public.iot_devices(id,tenant_id,site_id,zone_id) values('40000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001');
insert into public.vehicles(id,tenant_id,site_id,name,capacity,driver_id,shift_active) values('50000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','A shuttle',1,'00000000-0000-4000-8000-000000000003',true);
insert into public.stops(tenant_id,site_id,name) values('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','Community Hub'),('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','Demo Mall');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select is((select count(*)::int from public.tenants),1,'only own tenant');
select is((select count(*)::int from public.sites),1,'only assigned site, not second site');
select is((select count(*)::int from public.memberships),1,'only own membership');
select is((select count(*)::int from public.parking_zones),1,'parking isolated');
select is((select count(*)::int from public.iot_devices),0,'resident cannot enumerate devices');
select is((select count(*)::int from public.vehicles),0,'unassigned resident cannot track driver');
select throws_ok($$insert into public.tenants(name) values('evil')$$,'42501',null,'no direct writes');
select throws_ok($$select public.create_invitation('20000000-0000-4000-8000-000000000003')$$,'42501','Forbidden','same-tenant foreign site denied');
select throws_ok($$select public.simulate_parking('40000000-0000-4000-8000-000000000001',1)$$,'42501','Forbidden','resident cannot simulate');
select lives_ok($$select public.request_ride('60000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','Community Hub','Demo Mall',false)$$,'own ride request');
select lives_ok($$select public.request_ride('60000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000001','Community Hub','Demo Mall',false)$$,'second request');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select lives_ok($$select public.assign_ride('60000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000001')$$,'dispatcher assigns');
select throws_ok($$select public.assign_ride('60000000-0000-4000-8000-000000000002','50000000-0000-4000-8000-000000000001')$$,'P0001','Vehicle full','no overcapacity');
select lives_ok($$select public.simulate_parking('40000000-0000-4000-8000-000000000001',1)$$,'simulator uses persistence path');
select throws_ok($$select public.simulate_parking('40000000-0000-4000-8000-000000000001',3)$$,'P0001','Invalid or replayed event','capacity bounded');
select lives_ok($$select public.telemetry('50000000-0000-4000-8000-000000000001',3.1,101.5,10,now(),true)$$,'assigned driver GPS');
select lives_ok($$select public.set_shift('50000000-0000-4000-8000-000000000001',true)$$,'repeated shift start is idempotent');
select ok((select observed_at is not null from public.vehicles where id='50000000-0000-4000-8000-000000000001'),'repeated shift start preserves telemetry throttle timestamp');
select throws_ok($$select public.telemetry('50000000-0000-4000-8000-000000000001',3.1,101.5,10,now(),true)$$,'P0001','Invalid or throttled telemetry','GPS rate bounded');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select is((select count(*)::int from public.rides),0,'foreign tenant cannot see rides');
select is((select count(*)::int from public.visits),0,'foreign tenant cannot see visits');
select is((select count(*)::int from public.gps_observations),0,'foreign tenant cannot see history');
select is((select count(*)::int from public.audit_events),0,'audit requires capability');
reset role;
select is((select count(*)::int from pg_tables where schemaname='public' and not rowsecurity),0,'all application tables have RLS');
select * from finish();
rollback;
